/**
 * Sort order direction for configuration search results.
 *
 * Defines the two possible sorting directions: ascending (asc) and descending
 * (desc). Ascending order arranges results from smallest to largest (A-Z,
 * oldest to newest), while descending order arranges results from largest to
 * smallest (Z-A, newest to oldest).
 *
 * This enumeration provides consistent sorting behavior across all
 * configuration search operations, ensuring predictable result ordering for
 * users managing system settings.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ISortOrder = "asc" | "desc";
